package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsInterest decimal.Decimal = decimal.New(0, 0)
var WsTotal decimal.Decimal = decimal.New(0, 0)
var WsCount int64 = 0
var WsPrinEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string  // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var curLoan LoanRec
var loanFile *os.File
var loanScanner *bufio.Scanner

func InputDone() bool {
	return WsEofFlag == "Y"
}

func parseDecimalField(s string, scale int) decimal.Decimal {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return decimal.Zero
	}
	n, err := strconv.ParseInt(trimmed, 10, 64)
	if err != nil {
		// filter digits, keep leading minus
		neg := false
		var b strings.Builder
		for i, ch := range trimmed {
			if ch == '-' && i == 0 {
				neg = true
				continue
			}
			if ch >= '0' && ch <= '9' {
				b.WriteRune(ch)
			}
		}
		ds := b.String()
		if ds == "" {
			return decimal.Zero
		}
		n, err = strconv.ParseInt(ds, 10, 64)
		if err != nil {
			return decimal.Zero
		}
		if neg {
			n = -n
		}
	}
	return decimal.New(n, int32(-scale))
}

func parseIntField(s string) int64 {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return 0
	}
	n, err := strconv.ParseInt(trimmed, 10, 64)
	if err != nil {
		neg := false
		var b strings.Builder
		for i, ch := range trimmed {
			if ch == '-' && i == 0 {
				neg = true
				continue
			}
			if ch >= '0' && ch <= '9' {
				b.WriteRune(ch)
			}
		}
		ds := b.String()
		if ds == "" {
			return 0
		}
		n, err = strconv.ParseInt(ds, 10, 64)
		if err != nil {
			return 0
		}
		if neg {
			n = -n
		}
	}
	return n
}

func storeDecimal(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	sign := val.Sign()
	absVal := val.Abs()
	intPart := absVal.Truncate(0)
	fracPart := absVal.Sub(intPart)
	pow10 := decimal.New(1, int32(intDigits))
	var intMod decimal.Decimal
	if intPart.Cmp(pow10) >= 0 {
		intMod = intPart.Mod(pow10)
	} else {
		intMod = intPart
	}
	resultAbs := intMod.Add(fracPart)
	if sign < 0 {
		resultAbs = resultAbs.Neg()
	}
	return resultAbs
}

func storeCount(v int64) int64 {
	if v >= 0 {
		return v % 100000
	}
	av := -v
	av = av % 100000
	return -av
}

func formatEdited(val decimal.Decimal, mask string) string {
	dotIdx := strings.Index(mask, ".")
	var intMask, decMask string
	if dotIdx >= 0 {
		intMask = mask[:dotIdx]
		decMask = mask[dotIdx+1:]
	} else {
		intMask = mask
		decMask = ""
	}
	intDigitCount := 0
	for _, ch := range intMask {
		if ch == 'Z' || ch == '9' {
			intDigitCount++
		}
	}
	decDigitCount := 0
	for _, ch := range decMask {
		if ch == 'Z' || ch == '9' {
			decDigitCount++
		}
	}
	isNeg := val.Sign() < 0
	absVal := val.Abs()
	absVal = absVal.Round(int32(decDigitCount))

	var intStrFull string
	var fracStr string
	if decDigitCount > 0 {
		s := absVal.StringFixed(int32(decDigitCount))
		parts := strings.SplitN(s, ".", 2)
		intStrFull = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", decDigitCount)
		}
		if strings.HasPrefix(intStrFull, "-") {
			intStrFull = intStrFull[1:]
		}
	} else {
		s := absVal.StringFixed(0)
		if strings.HasPrefix(s, "-") {
			s = s[1:]
		}
		intStrFull = s
	}
	// high-order drop / pad
	if len(intStrFull) > intDigitCount {
		intStrFull = intStrFull[len(intStrFull)-intDigitCount:]
	} else if len(intStrFull) < intDigitCount {
		intStrFull = strings.Repeat("0", intDigitCount-len(intStrFull)) + intStrFull
	}
	digitRunes := []rune(intStrFull)
	intOut := make([]rune, len(intMask))
	suppressed := true
	dIdx := 0
	for i, ch := range intMask {
		if ch == 'Z' || ch == '9' {
			d := digitRunes[dIdx]
			dIdx++
			if ch == 'Z' {
				if suppressed && d == '0' {
					intOut[i] = ' '
				} else {
					suppressed = false
					intOut[i] = d
				}
			} else { // '9'
				suppressed = false
				intOut[i] = d
			}
		} else if ch == ',' {
			if suppressed {
				intOut[i] = ' '
			} else {
				intOut[i] = ','
			}
		} else {
			intOut[i] = ch
		}
	}
	result := string(intOut)
	if decDigitCount > 0 {
		// ensure fracStr length
		if len(fracStr) < decDigitCount {
			fracStr = fracStr + strings.Repeat("0", decDigitCount-len(fracStr))
		} else if len(fracStr) > decDigitCount {
			fracStr = fracStr[:decDigitCount]
		}
		result += "." + fracStr
	}
	if isNeg {
		if len(result) > 0 && result[0] == ' ' {
			result = "-" + result[1:]
		} else {
			result = "-" + result
		}
	}
	return result
}

// Paragraphs

func ReadPara() {
	if loanScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if loanScanner.Scan() {
		line := loanScanner.Text()
		if len(line) < 21 {
			line = line + strings.Repeat(" ", 21-len(line))
		} else if len(line) > 21 {
			line = line[:21]
		}
		curLoan.LrAcct = line[0:6]
		principalStr := line[6:15]
		curLoan.LrPrincipal = parseDecimalField(principalStr, 2)
		rateStr := line[15:19]
		curLoan.LrRate = parseDecimalField(rateStr, 2)
		yearsStr := line[19:21]
		curLoan.LrYears = parseIntField(yearsStr)
	} else {
		if err := loanScanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	tmp := curLoan.LrPrincipal.Mul(curLoan.LrRate)
	tmp = tmp.Mul(decimal.NewFromInt(curLoan.LrYears))
	tmp = tmp.Shift(-2)
	rounded := tmp.Round(2)
	WsInterest = storeDecimal(rounded, 9, 2)
	WsTotal = storeDecimal(WsTotal.Add(WsInterest), 11, 2)
	WsCount = storeCount(WsCount + 1)
	WsPrinEd = formatEdited(curLoan.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s\n", curLoan.LrAcct, WsPrinEd, WsIntEd)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func MainPara() {
	var err error
	loanFile, err = os.Open("input.dat")
	if err != nil {
		// treat as empty file
		WsEofFlag = "Y"
		loanScanner = nil
	} else {
		loanScanner = bufio.NewScanner(loanFile)
		buf := make([]byte, 0, 64*1024)
		loanScanner.Buffer(buf, 1024*1024)
	}
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	if loanFile != nil {
		loanFile.Close()
	}
	SummaryPara()
}

func main() {
	MainPara()
}
